import pandas as pd
import os

print("--- FINALIZING SHELTER TRAINING PANEL ---")

# This points to the dataset generated by Copilot (or your dummy data script)
file_path = "../data_internal/FINAL_MODEL_TRAIN.csv" 

try:
    shelter_panel = pd.read_csv(file_path)
except FileNotFoundError:
    print(f"CRITICAL ERROR: Could not find '{file_path}'.")
    print("Check your data_internal folder to ensure the file exists and is named correctly.")
    exit()

print(f"Loaded base shelter panel: {len(shelter_panel)} rows.")

# Calculate the 85th percentile threshold strictly localized to EACH shelter's history
print("Calculating localized 85th percentile surge thresholds...")
shelter_panel["Surge_Threshold_85"] = shelter_panel.groupby("ShelterName_Clean")[
    "TotalAdmissions"
].transform(lambda x: x.quantile(0.85))

# Create the binary target variable (1 = Surge, 0 = Normal)
shelter_panel["Admission_Surge_Flag"] = (
    shelter_panel["TotalAdmissions"] >= shelter_panel["Surge_Threshold_85"]
).astype(int)

# Verify the Target Variable
total_surges = shelter_panel["Admission_Surge_Flag"].sum()
print(f"Target variable created. Identified {total_surges} surge events across all shelters.")

# Save the Final Model-Ready Panel
os.makedirs("../outputs", exist_ok=True)
output_path = "../outputs/MODEL_TRAINING_PANEL_FINAL.csv"
shelter_panel.to_csv(output_path, index=False)

print(f"Success! Final training panel saved to {output_path}")
print(shelter_panel[["ShelterName_Clean", "YearMonth", "TotalAdmissions", "Surge_Threshold_85", "Admission_Surge_Flag"]].head())
